import React, { useEffect, useRef, useState } from "react";
import { Html5Qrcode } from "html5-qrcode";

function QRScanner() {
  const scannerRef = useRef(null);
  const [student, setStudent] = useState(null);
  const [status, setStatus] = useState("");

  useEffect(() => {

    const startScanner = async () => {

      try {

        const scanner = new Html5Qrcode("reader");
        scannerRef.current = scanner;

        const cameras = await Html5Qrcode.getCameras();

        if (cameras && cameras.length) {

          const cameraId = cameras[0].id;

          await scanner.start(
            cameraId,
            {
              fps: 10,
              qrbox: { width: 250, height: 250 }
            },

            async (decodedText) => {

              console.log("Scanned:", decodedText);

              try {

                const res = await fetch(
                  `http://localhost:5000/verify-user/${decodedText}`
                );

                const data = await res.json();

                if (data.success) {

                  setStudent(data.user);

                  const attendance = await fetch(
                    `http://localhost:5000/mark-attendance/${decodedText}`,
                    { method: "PUT" }
                  );

                  const result = await attendance.json();

                  if (result.success) {
                    setStatus("success");
                  } else {
                    setStatus("already");
                  }

                } else {

                  setStatus("notfound");

                }

              } catch (err) {

                console.log(err);
                setStatus("servererror");

              }

            }
          );

        } else {

          alert("No camera found");

        }

      } catch (err) {

        console.log("Camera error:", err);

      }

    };

    setTimeout(startScanner, 500);

    return () => {

      if (scannerRef.current) {

        scannerRef.current.stop()
          .then(() => scannerRef.current.clear())
          .catch(() => {});

      }

    };

  }, []);

  return (
    <div style={{ textAlign: "center", marginTop: "40px" }}>

      <h2>QR Attendance Scanner</h2>

      <div
        id="reader"
        style={{
          width: "350px",
          height: "350px",
          margin: "auto",
          border: "3px solid black"
        }}
      ></div>

      {student && (
        <div style={{ marginTop: "20px" }}>

          <h3>{student.name}</h3>
          <p>{student.college_name}</p>

          {status === "success" && (
            <h2 style={{ color: "green" }}>✔ Attendance Marked</h2>
          )}

          {status === "already" && (
            <h2 style={{ color: "red" }}>Already Scanned</h2>
          )}

          {status === "notfound" && (
            <h2 style={{ color: "orange" }}>User Not Found</h2>
          )}

        </div>
      )}

    </div>
  );
}

export default QRScanner;
